 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]

    def line_coords(values, length):
        coords = []
        for i, vals in enumerate(values):
            color, n = Counter(vals).most_common(1)[0]
            if color != background and n >= max(3, int(length * 0.65)):
                coords.append((i, color))
        return coords

    rows = line_coords(grid, w)
    cols = line_coords([[grid[r][c] for r in range(h)] for c in range(w)], h)
    line_color = Counter(color for _, color in rows + cols).most_common(1)[0][0]
    rpos = [r for r, _ in rows]
    cpos = [c for c, _ in cols]
    out = []
    for r1, r2 in zip(rpos, rpos[1:]):
        row = []
        for c1, c2 in zip(cpos, cpos[1:]):
            corners = [grid[r1][c1], grid[r1][c2], grid[r2][c1], grid[r2][c2]]
            if corners[0] == corners[1] == corners[2] == corners[3] and corners[0] not in (background, line_color):
                row.append(corners[0])
            else:
                row.append(background)
        out.append(row)
    return out


if __name__ == '__main__':
    pass
